# === Build output ===
out = {
    "target": {
        "repo": "Vaibhav91one/juice-shop",
        "ref": "1867b926c5f50e4e692dc9c8f61821413cebe0cd",
        "tag": "v17.3.0",
        "note": "The already-pinned BountyDesk demo target. No second app was added: see docs/benchmark.md for why XBOW validation-benchmarks apps were left out of this starter set."
    },
    "cases": C
}

# Validation
ids = [c["id"] for c in C]
assert len(set(ids)) == len(ids), "Duplicate ids"
required = ["id","split","kind","expected","title","body","rationale","source"]
for c in C:
    for f in required:
        assert f in c and c[f], f"Missing {f} in {c['id']}"
    if c["kind"] == "negative":
        assert "negativeType" in c, f"Missing negativeType in {c['id']}"

ntype_count = Counter(c.get("negativeType","-") for c in C if c["kind"]=="negative")
print(f"Total: {len(C)} | Pos: {sum(1 for c in C if c['kind']=='positive')} | Neg: {sum(1 for c in C if c['kind']=='negative')}")
print(f"Splits: {dict(Counter(c['split'] for c in C))}")
print(f"Neg types: {dict(ntype_count)}")
assert all(v == 20 for v in ntype_count.values())
assert sum(1 for c in C if c['kind']=='positive') == 20
assert sum(1 for c in C if c['kind']=='negative') == 100
print("All assertions passed!")

with open("bench/corpus.json", "w") as f:
    json.dump(out, f, indent=2)
    f.write("\n")
print("Written bench/corpus.json")
